// Weekly digest: ads that became "winning" in the lookback window, and new launches.
// Config is read from the Edit Fields node so a failed or empty Apify response still has thresholds.
function getConfig() {
  try {
    return $('Configure competitors and thresholds').first().json || {};
  } catch (error) {
    return ($input.first() && $input.first().json) || {};
  }
}

const config = getConfig();
const daysThreshold = Number(config.daysThreshold) || 30;
const lookbackDays = Number(config.lookbackDays) || 7;
const slackChannel = String(config.slackChannel || '#competitor-ads').trim();

function flatten(item) {
  const j = item == null ? {} : item;
  if (Array.isArray(j)) return j;
  if (Array.isArray(j.data)) return j.data;
  if (typeof j === 'object' && Object.keys(j).length === 0) return [];
  if (j.error || j.errorMessage) {
    const raw = j.error && typeof j.error === 'object' ? (j.error.message || JSON.stringify(j.error)) : (j.error || j.errorMessage);
    return [{ status: 'request_failed', inputDomain: 'apify', detail: String(raw) }];
  }
  return [j];
}

const rows = $input.all().flatMap((item) => flatten(item.json));
const ok = rows.filter((row) => row && row.status === 'ok');
const other = rows.filter((row) => row && row.status && row.status !== 'ok' && row.status !== 'domain_summary');
if (rows.length === 0) {
  other.push({ inputDomain: '(none)', status: 'no_rows', detail: 'The Actor returned no items. Check the domains, region and your Apify credential.' });
}

const ageDays = (date) => (Date.now() - Date.parse(String(date) + 'T00:00:00Z')) / 864e5;
const newWinners = ok.filter((row) => row.isWinningAd && Number(row.daysActive) <= daysThreshold + lookbackDays);
const launches = ok.filter((row) => row.firstShownDate && ageDays(row.firstShownDate) <= lookbackDays);
const allWinners = ok.filter((row) => row.isWinningAd);

const line = (row) => {
  const domain = row.inputDomain || row.domain || 'unknown';
  const format = row.format || 'ad';
  const headline = row.headline ? ` · "${row.headline}"` : '';
  const days = row.daysActive != null ? ` · ${row.daysActive} days` : '';
  const url = row.transparencyUrl ? ` · <${row.transparencyUrl}|view>` : '';
  return `• *${domain}* · ${format}${headline}${days}${url}`;
};

const text = [
  `*Competitor Google Ads — weekly report* (${ok.length} ads checked, ${allWinners.length} winning ads running ${daysThreshold}+ days)`,
  `*New winning ads this week* (crossed ${daysThreshold} days, still running): ${newWinners.length}`,
  ...newWinners.slice(0, 15).map(line),
  `*New ads launched in the last ${lookbackDays} days*: ${launches.length}`,
  ...launches.slice(0, 15).map(line),
  other.length ? `_No ads / not checked: ${other.map((row) => `${row.inputDomain || 'unknown'} (${row.status}${row.detail ? ` — ${row.detail}` : ''})`).join(', ')}_` : '',
].filter(Boolean).join('\n');

const tag = (row, type) => ({ ...row, reportType: type });
return [{
  json: {
    text,
    slackChannel,
    adsCount: ok.length,
    newWinnersCount: newWinners.length,
    launchesCount: launches.length,
    ads: [...newWinners.map((row) => tag(row, 'New winner')), ...launches.map((row) => tag(row, 'New launch'))],
  },
}];
